let backupBusy=false;
async function backupRequest(path,method='GET',body){
 const response=await fetch('/api/owner-backups'+path,{method,headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'}),data=await response.json();
 if(!response.ok)throw Object.assign(Error(data.error||'Backup request failed'),{status:response.status,rescueId:data.rescueId});return data;
}
function showBackups(items){
 $('backupList').replaceChildren(...items.map(item=>{
  const li=document.createElement('li'),text=document.createElement('span'),verify=document.createElement('button'),download=document.createElement('button'),restore=document.createElement('button'),remove=document.createElement('button');
  text.textContent=item.createdAt+' · '+Math.ceil(item.bytes/1024)+' KiB · '+item.id+' ';verify.type='button';verify.textContent='Verify integrity';verify.setAttribute('aria-label','Verify backup '+item.id);
  verify.onclick=()=>backupOperation(async()=>{const result=await backupRequest('/'+item.id,'POST');$('backupStatus').textContent='Integrity verified: '+result.files.length+' files · '+item.id});download.type='button';download.textContent='Download backup';download.setAttribute('aria-label','Download backup '+item.id);download.onclick=()=>backupOperation(async()=>{const data=await backupRequest('/'+item.id),url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='playgg-backup-'+item.id+'.json';try{document.body.append(a);a.click();$('backupStatus').textContent='Verified backup download started: '+item.id}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}});restore.type='button';restore.textContent='Restore backup';restore.setAttribute('aria-label','Restore backup '+item.id);restore.onclick=()=>backupOperation(()=>confirmRestore(item));remove.type='button';remove.textContent='Delete backup';remove.setAttribute('aria-label','Delete backup '+item.id);remove.onclick=()=>backupOperation(()=>confirmDeleteBackup(item));for(const b of [verify,download,restore,remove])b.disabled=backupBusy;li.append(text,verify,download,restore,remove);return li;
 }));if(!items.length)$('backupStatus').textContent='No backups yet.';
}
async function confirmDeleteBackup(item){
 const dialog=document.createElement('dialog'),title=document.createElement('h2'),description=document.createElement('p'),label=document.createElement('label'),input=document.createElement('input'),confirm=document.createElement('button'),cancel=document.createElement('button'),message=document.createElement('p');
 dialog.id='deleteBackupDialog';dialog.setAttribute('aria-label','Delete local backup');title.textContent='Delete local backup';description.textContent='Permanently delete only this archive: '+item.id+'. Current tables, accounts and game state stay unchanged. Download a copy first if you need it.';label.textContent='Type the backup ID to confirm deletion ';input.autocomplete='off';input.setAttribute('aria-label','Confirm deletion ID');label.append(input);confirm.type=cancel.type='button';confirm.textContent='Delete archive';cancel.textContent='Cancel';confirm.disabled=true;message.setAttribute('role','status');let pending=false,finished=false;
 const closed=new Promise(resolve=>{dialog.onclose=()=>{dialog.remove();if(!finished)$('backupStatus').textContent='Deletion canceled.';resolve()}});input.oninput=()=>{confirm.disabled=pending||input.value!==item.id};cancel.onclick=()=>dialog.close();dialog.oncancel=e=>{if(pending)e.preventDefault()};confirm.onclick=async()=>{
  if(pending||input.value!==item.id)return;pending=true;input.disabled=confirm.disabled=cancel.disabled=true;message.textContent='Deleting archive…';
  try{await backupRequest('/'+item.id,'DELETE',{confirm:input.value});finished=true;$('backupStatus').textContent='Deleted backup: '+item.id;showBackups(await backupRequest(''));$('backupStatus').textContent='Deleted backup: '+item.id;dialog.close()}
  catch(error){pending=false;cancel.disabled=false;if(finished||!error.status||error.status>=500){finished=true;message.textContent='Check the backup list after reconnecting before retrying deletion.';$('backupStatus').textContent=message.textContent;cancel.textContent='Close'}else{message.textContent=error.message;input.disabled=false;confirm.disabled=input.value!==item.id}}
 };
 dialog.append(title,description,label,confirm,cancel,message);document.body.append(dialog);dialog.showModal();input.focus();await closed;
}
async function confirmRestore(item){
 const snapshot=await backupRequest('/'+item.id),dialog=document.createElement('dialog'),title=document.createElement('h2'),description=document.createElement('p'),id=document.createElement('code'),label=document.createElement('label'),input=document.createElement('input'),confirm=document.createElement('button'),cancel=document.createElement('button'),message=document.createElement('p');
 dialog.id='restoreBackupDialog';dialog.setAttribute('aria-label','Restore local backup');title.textContent='Restore local backup';description.textContent='Replace local tables, accounts, sessions, notes and game state with the backup from '+snapshot.createdAt+'. A rescue backup is created first. Active hands must finish. Players may need to sign in again.';id.textContent=item.id;label.textContent='Type the backup ID to confirm replacement ';input.autocomplete='off';input.setAttribute('aria-label','Confirm backup ID');label.append(input);confirm.type=cancel.type='button';confirm.textContent='Restore local state';cancel.textContent='Cancel';confirm.disabled=true;message.setAttribute('role','status');let pending=false,completed=false,uncertain=false;
 const closed=new Promise(resolve=>{dialog.onclose=()=>{dialog.remove();if(!completed&&!uncertain)$('backupStatus').textContent='Restore canceled.';resolve()}});input.oninput=()=>{confirm.disabled=pending||input.value!==item.id};cancel.onclick=()=>dialog.close();dialog.oncancel=e=>{if(pending)e.preventDefault()};confirm.onclick=async()=>{
  if(pending||input.value!==item.id)return;pending=true;input.disabled=confirm.disabled=cancel.disabled=true;message.textContent='Restoring local state…';
  try{const result=await backupRequest('/'+item.id+'/restore','POST',{confirm:input.value});completed=true;$('backupStatus').textContent='Restored: '+result.id+' · Rescue backup: '+result.rescueId;await refresh();showBackups(await backupRequest(''));$('audit').replaceChildren();const key=$('key').value;document.querySelector('form').reset();$('key').value=key;$('mode').onchange();$('result').textContent='Select a table to edit its restored settings.';$('backupStatus').textContent='Restored: '+result.id+' · Rescue backup: '+result.rescueId;completed=true;dialog.close()}
  catch(error){pending=false;cancel.disabled=false;if(completed){message.textContent='State restored; refresh this page to reload the owner console.';input.disabled=confirm.disabled=true;cancel.textContent='Close'}else if(!error.status||error.status===503){uncertain=true;message.textContent=error.status===503?error.message:'Restoration could not be confirmed. Reconnect and inspect backups before retrying.';$('backupStatus').textContent=message.textContent;input.disabled=confirm.disabled=true;cancel.textContent='Close'}else{message.textContent=error.message+(error.rescueId?' · Rescue backup: '+error.rescueId:'');input.disabled=false;confirm.disabled=input.value!==item.id}}
 };
 dialog.append(title,description,id,label,confirm,cancel,message);document.body.append(dialog);dialog.showModal();input.focus();await closed;
}
async function backupOperation(action){
 if(backupBusy)return;backupBusy=true;for(const button of $('backups').querySelectorAll('button'))button.disabled=true;$('backupStatus').textContent='Working…';
 try{await action()}catch(error){$('backupStatus').textContent=error.message}finally{backupBusy=false;for(const button of $('backups').querySelectorAll('button'))button.disabled=false}
}
$('loadBackups').onclick=()=>backupOperation(async()=>{showBackups(await backupRequest(''));if($('backupList').children.length)$('backupStatus').textContent='Private local backups.'});
$('createBackup').onclick=()=>backupOperation(async()=>{const result=await backupRequest('','POST');showBackups(await backupRequest(''));$('backupStatus').textContent='Backup created: '+result.id});

let chatBusy=false;
async function manageChat(table,command){
 if(chatBusy)return;chatBusy=true;$('chatModeration').hidden=false;$('chatHeading').textContent='Chat · '+table.name;$('chatOwnerStatus').textContent='Loading…';
 for(const button of document.querySelectorAll('#chatPlayers button,button[aria-label^="Manage chat for "]'))button.disabled=true;
 try{
  const r=await fetch('/api/owner-chat'+(command?'':'?table='+encodeURIComponent(table.id)),{method:command?'POST':'GET',headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},cache:'no-store',...(command?{body:JSON.stringify({tableId:table.id,...command})}:{})}),data=await r.json();if(!r.ok)throw Error(data.error);
  const players=command?data.players:data;
  $('chatPlayers').replaceChildren(...players.map(p=>{const li=document.createElement('li'),button=document.createElement('button');li.append(p.name+' · '+(p.seat===null?'observer · local account':p.accountBound?'local account':'guest seat')+' · '+(p.muted?'Muted':'Chat enabled')+' ');button.type='button';button.textContent=p.muted?'Unmute':'Mute';button.setAttribute('aria-label',(p.muted?'Unmute ':'Mute ')+p.name);button.onclick=()=>manageChat(table,{seat:p.seat,subject:p.subject,muted:!p.muted});li.append(button);return li}));
  $('chatOwnerStatus').textContent=data.auditSaved===false?'Moderation saved, but audit could not be written.':players.length?'Text and reactions only; game participation is unchanged.':'No human players seated.';
 }catch(error){$('chatPlayers').replaceChildren();$('chatOwnerStatus').textContent=error.message}
 finally{chatBusy=false;for(const button of document.querySelectorAll('#chatPlayers button,button[aria-label^="Manage chat for "]'))button.disabled=false}
}

$('loadReports').onclick=async()=>{try{const response=await fetch('/api/owner-reports',{headers:{Authorization:'Bearer '+$('key').value},cache:'no-store'}),rows=await response.json();if(!response.ok)throw Error(rows.error);$('reportsList').replaceChildren(...rows.reverse().map(row=>{const item=document.createElement('details'),title=document.createElement('summary'),text=document.createElement('p'),context=document.createElement('p'),state=document.createElement('select'),note=document.createElement('textarea'),save=document.createElement('button'),message=document.createElement('output');title.textContent=new Date(row.at).toLocaleString()+' · '+row.reporter+' → '+(row.kind==='profile'?row.reported:row.seats.map(i=>row.hand.names[i]).join(', '))+' · '+row.categoryLabel;text.textContent=row.detail;context.textContent=row.kind==='profile'?'Player report · '+row.eventName+' ('+row.event+') · No hand attached.':'Hand '+row.number+' · Board: '+(row.hand.board?.join(' ')||'No board')+' · Paid: '+(row.hand.payouts?.join(', ')||'Unavailable');state.append(new Option('Open','open'),new Option('Reviewed','reviewed'));state.value=row.status;state.setAttribute('aria-label','Report review state');note.value=row.reviewNote;note.maxLength=1000;note.setAttribute('aria-label','Administrator review note');save.type='button';save.textContent='Save review';message.setAttribute('role','status');save.onclick=async()=>{save.disabled=true;try{const r=await fetch('/api/owner-reports',{method:'POST',headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:JSON.stringify({id:row.id,status:state.value,note:note.value})}),result=await r.json();if(!r.ok)throw Error(result.error);message.textContent=' Review saved.'}catch(error){message.textContent=error.message}finally{save.disabled=false}};item.append(title,text,context,state,note,save,message);return item}));$('reportsStatus').textContent=rows.length+' local reports.'}catch(error){$('reportsStatus').textContent=error.message}};

let walletSequence=null,grantCommand=null,grantBusy=false;
function grantControls(disabled){for(const node of $('walletGrantForm').querySelectorAll('input,select,button'))node.disabled=disabled||walletSequence===null||!$('walletAccount').options.length;$('loadWallets').disabled=disabled}
async function loadWallets(){
 const response=await fetch('/api/owner-wallets',{headers:{Authorization:'Bearer '+$('key').value},cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error);
 const selected=$('walletAccount').value;walletSequence=data.nextSequence;$('walletAccount').replaceChildren(...data.accounts.map(a=>new Option(a.name,a.name)));if(data.accounts.some(a=>a.name===selected))$('walletAccount').value=selected;
 $('walletBalances').replaceChildren(...data.accounts.map(a=>{const li=document.createElement('li');li.dataset.account=a.name;li.dataset.balance=String(a.available);li.textContent=a.name+': '+a.available+' play chips';return li}));
 const events=data.accounts.flatMap(a=>a.events.filter(e=>e.kind==='owner-grant').map(e=>({...e,name:a.name}))).sort((a,b)=>b.at-a.at||b.sequence-a.sequence).slice(0,30);
 $('walletActivity').replaceChildren(...events.map(e=>{const li=document.createElement('li');li.textContent='#'+e.sequence+' · '+e.name+' +'+e.amount+' · '+e.reason;return li}));
}
$('loadWallets').onclick=async()=>{grantBusy=true;grantControls(true);try{await loadWallets();$('walletStatus').textContent=$('walletAccount').options.length?'Balances loaded.':'Register a local player before granting chips.'}catch(error){walletSequence=null;$('walletStatus').textContent=error.message}finally{grantBusy=false;grantControls(false)}};
$('walletGrantForm').oninput=()=>{if(!grantBusy)grantCommand=null};
$('walletGrantForm').onsubmit=async e=>{e.preventDefault();if(grantBusy||walletSequence===null)return;grantBusy=true;grantControls(true);let saved=false;try{
 grantCommand??={account:$('walletAccount').value,amount:Number($('walletAmount').value),reason:$('walletReason').value.trim(),sequence:walletSequence};
 const response=await fetch('/api/owner-wallets',{method:'POST',headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:JSON.stringify(grantCommand)}),data=await response.json();if(!response.ok)throw Error(data.error);
 saved=true;grantCommand=null;$('walletReason').value='';walletSequence=data.sequence+1;await loadWallets();$('walletStatus').textContent='Grant #'+data.sequence+' saved: '+data.amount+' play chips.';
 }catch(error){$('walletStatus').textContent=(saved?'Grant saved; balances could not refresh. ':'')+error.message+(saved?'':' Retry keeps the same operation number; reload balances to inspect recent activity.')}finally{grantBusy=false;grantControls(false)}};

// Local owner capitalization is separate from player-wallet grants.
let bankSequence=null,bankCommand=null,bankBusy=false,bankEpoch=0;
function bankControls(){for(const node of $('spinBankForm').querySelectorAll('input,button'))node.disabled=bankBusy||bankSequence===null;$('loadSpinBank').disabled=bankBusy}
function clearBank(){bankSequence=null;bankCommand=null;for(const id of ['spinBankAvailable','spinBankReserved','spinBankNet'])$(id).textContent='—';$('spinBankActivity').replaceChildren();$('spinBankStatus').textContent='';bankControls()}
$('key').addEventListener('input',()=>{bankEpoch++;clearBank()});
async function loadBank(epoch){const response=await fetch('/api/owner-spin-bank',{headers:{Authorization:'Bearer '+$('key').value},cache:'no-store',signal:AbortSignal.timeout(5000)}),data=await response.json();if(epoch!==bankEpoch)return false;if(!response.ok)throw Error(data.error);bankSequence=data.nextSequence;for(const [id,key]of [['spinBankAvailable','available'],['spinBankReserved','reserved'],['spinBankNet','net']])$(id).textContent=String(data[key]);const activity=data.events.slice().reverse().map(e=>'Funding #'+e.sequence+' · +'+e.amount+' · '+e.reason);for(const r of (data.reservations??[]).slice(-100).reverse())activity.push('Match '+r.id+' · stake '+r.buyIn+' · '+(r.cancelled?'cancelled':r.ticket===undefined?'reserved '+r.amount:'settled prize '+spinOutcome(r.buyIn,r.ticket).prizePool+' · bank net '+(3*r.buyIn-spinOutcome(r.buyIn,r.ticket).prizePool)));$('spinBankActivity').replaceChildren(...activity.map(text=>{const row=document.createElement('li');row.style.overflowWrap='anywhere';row.textContent=text;return row}));return true}
$('loadSpinBank').onclick=async()=>{if(bankBusy)return;bankBusy=true;bankControls();const epoch=bankEpoch;try{if(await loadBank(epoch))$('spinBankStatus').textContent='Spin bank loaded.'}catch(error){if(epoch===bankEpoch){clearBank();$('spinBankStatus').textContent=error.message}}finally{bankBusy=false;bankControls()}};
$('spinBankForm').oninput=()=>{if(!bankBusy)bankCommand=null};
$('spinBankForm').onsubmit=async event=>{event.preventDefault();if(bankBusy||bankSequence===null)return;bankBusy=true;bankControls();const epoch=bankEpoch;let saved=false;try{
 bankCommand??={sequence:bankSequence,amount:Number($('spinBankAmount').value),reason:$('spinBankReason').value.trim()};const response=await fetch('/api/owner-spin-bank',{method:'POST',headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:JSON.stringify(bankCommand),signal:AbortSignal.timeout(5000)}),data=await response.json();if(epoch!==bankEpoch)return;if(!response.ok)throw Error(data.error);saved=true;bankCommand=null;bankSequence=data.sequence+1;$('spinBankReason').value='';if(await loadBank(epoch))$('spinBankStatus').textContent='Funding #'+data.sequence+' saved.';
 }catch(error){if(epoch===bankEpoch)$('spinBankStatus').textContent=(saved?'Funding saved; reload the bank. ':'')+error.message+(saved?'':' Retry keeps the same funding number.')}finally{bankBusy=false;bankControls()}};

// Explicit owner practice rules never supply recovered native defaults.
