$('spinRulesForm').onsubmit=async event=>{event.preventDefault();if(spinRulesBusy||spinRulesData?.nextRevision==null)return;spinRulesBusy=true;spinRulesControls();const epoch=spinRulesEpoch;let saved=false;try{const buyIn=Number($('spinRulesStake').value);spinRulesPending??={revision:spinRulesData.nextRevision,buyIn,configuration:{mode:'local-practice',outcomes:spinPayouts(buyIn).map(r=>({multiplier:r.multiplier,startingChips:Number($('spinRuleStack'+r.multiplier).value),timeBankCards:Number($('spinRuleCards'+r.multiplier).value),noDealing:false}))},clock:{actionSeconds:Number($('spinRulesAction').value),freeTimeChipSecondsPerUnit:Number($('spinRulesSeconds').value),maxTimeChipsPerAction:Number($('spinRulesMax').value)},...($('spinRulesInsuranceEnabled').checked?{insurance:{premium:Number($('spinRulesInsurancePremium').value),payout:Number($('spinRulesInsurancePayout').value)}}:{}),reason:$('spinRulesReason').value.trim()};if($('spinRulesFormat').value==='6'&&spinRulesPending.configuration.seats!==6)spinRulesPending.configuration=sixRuleDraft(buyIn,spinRulesPending.clock);const r=await fetch('/api/owner-spin-rules',{method:'POST',headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:JSON.stringify(spinRulesPending),signal:AbortSignal.timeout(5000)}),data=await r.json();if(epoch!==spinRulesEpoch)return;if(!r.ok)throw Error(data.error);saved=true;spinRulesPending=null;if(await loadSpinRules(epoch))$('spinRulesStatus').textContent='Practice rules #'+data.revision+' saved.'}catch(error){if(epoch===spinRulesEpoch)$('spinRulesStatus').textContent=(saved?'Rules saved; reload to inspect. ':'')+error.message+(saved?'':' Retry keeps the same revision.')}finally{spinRulesBusy=false;spinRulesControls()}};
