async function ownerRequest(method,body,path='/api/owner-battle'){if(!$('key').value)throw Error('Enter the owner key first');const response=await fetch(path,{method,headers:{Authorization:'Bearer '+$('key').value,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(5000)}),data=await response.json();if(!response.ok)throw Error(data.error);return data}
