$('loadBattleEvents').onclick=async()=>{if(battleBusy)return;battleBusy=true;battleControls();const epoch=battleEpoch;try{const events=await ownerRequest('GET');if(epoch!==battleEpoch)return;paintBattleEvents(events);$('battleStatus').textContent=events.length?'Events loaded.':'No Battle Royale events.'}catch(error){if(epoch===battleEpoch)$('battleStatus').textContent=error.message}finally{battleBusy=false;battleControls()}};
$('battleEventForm').onsubmit=async event=>{event.preventDefault();if(battleBusy)return;const settings={id:$('battleId').value,name:$('battleName').value,capacity:Number($('battleCapacity').value),stack:Number($('battleStack').value),blind:Number($('battleBlind').value),finalSeats:Number($('battleFinalSeats').value),rushDurationMs:Number($('battleRushSeconds').value)*1000,entryCost:Number($('battleEntryCost').value),...($('battlePrizeShares').value.trim()?{prizeShares:$('battlePrizeShares').value.split(',').map(v=>Number(v.trim()))}:{})};battleBusy=true;battleControls();const epoch=battleEpoch;let saved=false;try{const result=await ownerRequest('POST',settings);saved=true;if(epoch!==battleEpoch)return;if(!$('battleBountyId').value)$('battleBountyId').value=settings.id;$('battleStatus').textContent='Created '+settings.name+'.'+(result.auditSaved===false?' Audit log could not be written.':'');const events=await ownerRequest('GET');if(epoch===battleEpoch)paintBattleEvents(events)}catch(error){if(epoch===battleEpoch)$('battleStatus').textContent=(saved?'Event created; list refresh failed. ':'')+error.message}finally{battleBusy=false;battleControls()}};

function battleBountyInventory(){
 const input=$('battleBountyItems'),lines=input.value.trim().split(/\r?\n/),items=[];let capital=0;
 for(const line of lines){const m=/^\s*(\d+)\s*[x×]\s*(\d+)\s*$/i.exec(line);if(!m){input.setCustomValidity('Use one amount x count per line, for example 11 x 1');$('battleBountyCapital').value='';return null}const amount=Number(m[1]),frequency=Number(m[2]);if(!Number.isSafeInteger(amount)||amount<1||!Number.isSafeInteger(frequency)||frequency<1||frequency>10000||items.some(p=>p.amount===amount)){input.setCustomValidity('Use unique positive whole amounts and counts up to 10000');$('battleBountyCapital').value='';return null}items.push({amount,frequency});capital+=amount*frequency}
 if(items.length>100||items.reduce((n,p)=>n+p.frequency,0)>10000||!Number.isSafeInteger(capital)||capital>1000000000){input.setCustomValidity('Use at most 100 amounts,10000 items and1000000000 play credits');$('battleBountyCapital').value='';return null}
 input.setCustomValidity('');$('battleBountyCapital').value=String(capital);return items;
}
$('battleBountyItems').oninput=battleBountyInventory;
$('battleBountyForm').onsubmit=async event=>{event.preventDefault();if(battleBusy)return;const items=battleBountyInventory();if(!items){$('battleBountyForm').reportValidity();return}const body={id:$('battleBountyId').value,capital:Number($('battleBountyCapital').value),items,reason:$('battleBountyReason').value},epoch=battleEpoch;let saved=false;battleBusy=true;battleControls();try{const result=await ownerRequest('POST',body,'/api/owner-battle-bounty');saved=true;if(epoch!==battleEpoch)return;$('battleStatus').textContent='Bounty inventory saved · capital '+result.capital+' · '+result.remaining+' remaining play credits.'+(result.auditSaved===false?' Audit log could not be written.':'');const events=await ownerRequest('GET');if(epoch===battleEpoch)paintBattleEvents(events)}catch(error){if(epoch===battleEpoch)$('battleStatus').textContent=(saved?'Bounty capital saved; list refresh failed. ':'')+error.message}finally{battleBusy=false;battleControls()}};

