function multiControls(){for(const e of $('multiForm').elements)e.disabled=multiBusy;$('loadMulti').disabled=multiBusy;for(const b of $('multiEvents').querySelectorAll('button'))b.disabled=multiBusy}
function paintMulti(events){$('multiEvents').replaceChildren(...events.map(e=>{const row=document.createElement('li');row.dataset.multiEvent=e.id;row.textContent=e.name+' · '+e.registered+' / '+e.settings.capacity+' · '+(e.status==='cancelled'?'Cancelled · entries refunded':e.status==='cancelling'?'Cancellation pending · finish current hands':e.status==='complete'?'Finished':e.paused?'Paused':e.pauseRequested?'Pause after current hands':e.status==='registering'?'Registration open':e.tournament.tables.some(t=>t.number>0)?'Playing':'Waiting for players')+' · pool '+(e.status==='cancelled'?0:e.tournament?.pool??e.registered*e.settings.entryCost)+' play credits'+(e.tournament?.winner?' · winner '+e.tournament.winner:'');if(!['complete','cancelled','cancelling'].includes(e.status)){const cancel=document.createElement('button');cancel.type='button';cancel.dataset.multiCancel=e.id;cancel.textContent='Cancel tournament and refund entries';cancel.onclick=()=>void controlMulti(e,'cancel');row.append(document.createTextNode(' '),cancel);if(e.status==='allocated'){const pause=document.createElement('button'),action=e.paused||e.pauseRequested?'resume':'pause';pause.type='button';pause.dataset.multiControl=e.id;pause.dataset.action=action;pause.textContent=action==='resume'?'Resume tournament':'Pause after current hands';pause.onclick=()=>void controlMulti(e,action);row.append(document.createTextNode(' '),pause)}}return row}))}
$('loadMulti').onclick=async()=>{if(multiBusy)return;multiBusy=true;multiControls();const epoch=multiEpoch;try{const data=await ownerRequest('GET',undefined,'/api/owner-multi-tournaments');if(epoch===multiEpoch){paintMulti(data);$('multiStatus').textContent='Tournaments loaded.'}}catch(e){if(epoch===multiEpoch)$('multiStatus').textContent=e.message}finally{multiBusy=false;multiControls()}};
$('multiForm').onsubmit=async event=>{event.preventDefault();if(multiBusy)return;const command={id:$('multiId').value,name:$('multiName').value,settings:{capacity:Number($('multiCapacity').value),startingStack:Number($('multiStack').value),entryCost:Number($('multiEntry').value),prizeShares:$('multiShares').value.split(',').map(v=>Number(v.trim())),blind:Number($('multiBlind').value),levelSeconds:Number($('multiLevel').value),actionSeconds:Number($('multiAction').value),...(Number($('multiTimeBank').value)>0?{timeBankSeconds:Number($('multiTimeBank').value),hotTimeSeconds:Number($('multiHotTime').value)}:{}),seatingPolicy:'local-idle-balance-v1',rankingPolicy:'local-settlement-order-v1'}};multiBusy=true;multiControls();const epoch=multiEpoch;let saved=false;try{const result=await ownerRequest('POST',command,'/api/owner-multi-tournaments');saved=true;if(epoch!==multiEpoch)return;$('multiStatus').textContent='Created '+result.name+'.'+(result.auditSaved===false?' Audit log could not be written.':'');const events=await ownerRequest('GET',undefined,'/api/owner-multi-tournaments');if(epoch===multiEpoch)paintMulti(events)}catch(e){if(epoch===multiEpoch)$('multiStatus').textContent=(saved?'Created; list refresh failed. ':'')+e.message+' Retry with the same identity to avoid duplicate events.'}finally{multiBusy=false;multiControls()}};

async function controlMulti(event,action){if(multiBusy)return;multiBusy=true;multiControls();const epoch=multiEpoch;try{const result=await ownerRequest('POST',{id:event.id,revision:event.revision,action},'/api/owner-multi-tournaments');if(epoch!==multiEpoch)return;$('multiStatus').textContent=action==='resume'?'Tournament resumed.':action==='pause'?(result.paused?'Tournament paused; blind clock stopped.':'Pause requested; current hands finish first.'):result.status==='cancelled'?'Tournament cancelled; entries refunded.':'Cancellation requested; current hands finish before refunds.';const events=await ownerRequest('GET',undefined,'/api/owner-multi-tournaments');if(epoch===multiEpoch)paintMulti(events)}catch(error){if(epoch===multiEpoch)$('multiStatus').textContent=error.message+' Reload tournaments before retrying.'}finally{multiBusy=false;multiControls()}}
